        }
        return p
    }()

    // Proiezione equirettangolare calibrata sul viewBox 100×131.2 (come projX/projY in LeadsCardGrid.tsx)
    static func projX(_ lon: Double) -> CGFloat { CGFloat((lon - 12.3908) * 8.337 + 48.5) }
    static func projY(_ lat: Double) -> CGFloat { CGFloat((43.1107 - lat) * 11.328 + 45) }
}
